#if UNITY_EDITOR
using LastRail.Battle;
using NUnit.Framework;
using System;
using System.IO;
using System.Linq;
using Newtonsoft.Json.Linq;
namespace LastRail.Tests.EditMode {
 public sealed class BTravelMaintenanceTests {
  const string Qa="D:/Project/LASTRAIL/QA/CombatBMigration-20261004/BTravelMaintenance-20261005/";
  static JObject Rail(){var c=global::CombatRailJourneyTests.Config();c["offers"]=new JArray();c["throttleMaximumBps"]=13000;c["throttleCruiseBps"]=10000;return c;}
  static BDirectAttackBasicLoop Native(JObject config=null,int capacity=10000){var f=BNamedOperatorSourceTests.Native();var c=config??Rail();return BDirectAttackBasicLoop.CreateOrdinaryTravelRuntime(f.binding,BInterceptSourceTests.Read(BInterceptSourceTests.Sample()).OriginalSource,BOrdinaryGeometryTests.Geometry(f.binding),capacity,c,BDirectAttackInput.Digest(c));}
  static long Distance(BDirectAttackBasicLoop n)=>(long)n.Capture()["travel"]["motion"]["distanceMm"];
  [Test] public void ComposedSourceUsesAcceptedOwnersAndFencesResumeRestoreAndLifetime(){
   var n=Native();var s=new BTravelMaintenanceObservationSource(n);
   Assert.IsFalse((bool)s.Capture()["combatStopped"]);
   n.Advance("moving-source",10000000,500);s.ObserveAccepted("moving-source",0);
   n.SetPaused("hold-source",true);var p=s.ObserveAccepted("hold-source",1);
   Assert.IsTrue((bool)p["combatStopped"]);Assert.IsTrue((bool)p["travelStopped"]);Assert.IsFalse((bool)p["hazardsSettled"]);
   Assert.AreEqual(10000,(long)p["travel"]["motion"]["distanceMm"]);Assert.IsFalse(s.CanPrepareTrustedMaintenance);
   var h=(string)p["originalObservation"]["nativeHash"];s.RequireUnchanged(2,h);
   using(var restored=BTravelMaintenanceObservationSource.Restore(n,p,BDirectAttackInput.Digest(p)))Assert.IsTrue(JToken.DeepEquals(p,restored.Capture()));
   var forged=(JObject)p.DeepClone();forged["hazardsSettled"]=true;
   Assert.Throws<ArgumentException>(()=>BTravelMaintenanceObservationSource.Restore(n,forged,BDirectAttackInput.Digest(forged)));
   Assert.Throws<ArgumentException>(()=>BTravelMaintenanceObservationSource.Restore(n,p,"wrong"));
   n.SetPaused("resume-source",false);Assert.Throws<InvalidOperationException>(()=>s.RequireUnchanged(2,h));
   s.ObserveAccepted("resume-source",2);Assert.IsFalse((bool)s.Capture()["travelStopped"]);
   Assert.Throws<InvalidOperationException>(()=>s.RequireTrustedMaintenance());
   File.WriteAllText(Qa+"composed-travel-observation.json",s.Capture().ToString());
   s.Dispose();Assert.Throws<ObjectDisposedException>(()=>s.Capture());Assert.Throws<ObjectDisposedException>(()=>s.ObserveAccepted("late",3));
   n.Advance("borrowed-owner-still-alive",10000000,500);Assert.AreEqual(20000,Distance(n));
  }
  [Test] public void NativeTravelObservationNeedsOwnCompositionOverCompletedBaseSource(){Assert.NotNull(typeof(BDirectAttackInput).Assembly.GetType("LastRail.Battle.BTravelMaintenanceObservationSource"));}
  [Test] public void DistanceOverflowInStagedStepDoesNotPublishClockHpOrCommand(){var n=Native();var flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;var travel=typeof(BDirectAttackBasicLoop).GetField("travel",flags).GetValue(n);var motion=travel.GetType().GetField("motion",flags).GetValue(travel);typeof(CombatRailJourney).GetField("distanceMm",flags).SetValue(motion,long.MaxValue);var before=n.Capture();Assert.Throws<OverflowException>(()=>n.Advance("fault-injected-distance-overflow",10000000,500));Assert.IsTrue(JToken.DeepEquals(before,n.Capture()));}
  [Test] public void NativeTravelNeedsExplicitFactoryOnOriginalFixedStep(){Assert.NotNull(typeof(BDirectAttackBasicLoop).GetMethod("CreateOrdinaryTravelRuntime"));}
  [Test] public void ActualBStepsDriveMotionPauseDistanceDebtAndResumeFromSameOwner(){var n=Native();var before=n.Capture();n.Advance("moving",10000000,500);var moved=n.Capture();Assert.AreEqual(10000,Distance(n));Assert.AreEqual(n.Tick,(long)moved["travel"]["motion"]["currentTick"]);n.SetPaused("pause",true);var paused=n.Capture();n.Advance("held",100000000,500);Assert.AreEqual(10000,Distance(n));Assert.IsTrue((bool)n.Capture()["travel"]["stopped"]);Assert.IsTrue(JToken.DeepEquals(paused["state"]["direct"]["clock"],n.Capture()["state"]["direct"]["clock"]));n.SetPaused("resume",false);n.Advance("moving-again",10000000,500);Assert.AreEqual(20000,Distance(n));Assert.IsFalse((bool)n.Capture()["travel"]["stopped"]);Assert.IsTrue(JToken.DeepEquals(before["travel"]["origin"],n.Capture()["travel"]["origin"]));File.WriteAllText(Qa+"actual-travel-stages.json",new JObject{["before"]=before,["moved"]=moved,["paused"]=paused,["resumed"]=n.Capture()}.ToString());}
  [Test] public void OriginalSpeedAndThrottleRemainSeparateAndPartitionPreservesFraction(){var c=Rail();c["baseSpeedMillimetersPerSecond"]=3;var a=Native(c);var b=Native(c);a.SetTravelThrottle("throttle",7000);b.SetTravelThrottle("throttle",7000);a.Advance("all",10000000,500);for(int i=0;i<10;i++)b.Advance("part"+i,1000000,50);Assert.IsTrue(JToken.DeepEquals(a.Capture()["travel"]["motion"],b.Capture()["travel"]["motion"]));Assert.AreEqual(2,Distance(a));Assert.AreEqual("0.1",(string)a.Capture()["travel"]["motion"]["distanceRemainder"]);var n=Native();n.SetSpeed("double",4);n.Advance("double-step",10000000,1000);Assert.AreEqual(20000,Distance(n));Assert.AreEqual(10000,(long)n.Capture()["travel"]["motion"]["throttleBps"]);}
  [Test] public void DuplicateConflictingPausedAndFailedControlsCannotPublishTravelChanges(){var n=Native();n.SetTravelThrottle("t",7000);var p=n.Capture();n.SetTravelThrottle("t",7000);Assert.IsTrue(JToken.DeepEquals(p,n.Capture()));Assert.Throws<ArgumentException>(()=>n.SetTravelThrottle("t",13000));Assert.IsTrue(JToken.DeepEquals(p,n.Capture()));Assert.Throws<ArgumentOutOfRangeException>(()=>n.SetTravelThrottle("outside-original-range",6999));Assert.IsTrue(JToken.DeepEquals(p,n.Capture()));n.SetPaused("hold",true);p=n.Capture();Assert.Throws<ArgumentException>(()=>n.SetTravelThrottle("during-pause",13000));Assert.IsTrue(JToken.DeepEquals(p,n.Capture()));}
  [Test] public void OriginalReplayPinsMotionNodeConfigurationAndAcceptedPrefix(){var f=BNamedOperatorSourceTests.Native();var node=BInterceptSourceTests.Read(BInterceptSourceTests.Sample()).OriginalSource;var g=BOrdinaryGeometryTests.Geometry(f.binding);var c=Rail();var n=BDirectAttackBasicLoop.CreateOrdinaryTravelRuntime(f.binding,node,g,10000,c,BDirectAttackInput.Digest(c));n.SetTravelThrottle("t",7000);n.Advance("before-pause",10000000,500);n.SetPaused("p",true);var snapshot=n.Capture();var r=BDirectAttackBasicLoop.RestoreOrdinaryTravelRuntime(snapshot,BDirectAttackInput.Digest(snapshot),f.binding,node,g,10000,c,BDirectAttackInput.Digest(c));Assert.IsTrue(JToken.DeepEquals(snapshot,r.Capture()));n.SetPaused("r",false);r.SetPaused("r",false);n.Advance("continue",10000000,500);r.Advance("continue",10000000,500);Assert.IsTrue(JToken.DeepEquals(n.Capture(),r.Capture()));var forged=(JObject)snapshot.DeepClone();forged["travel"]["motion"]["distanceMm"]=1;Assert.Throws<ArgumentException>(()=>BDirectAttackBasicLoop.RestoreOrdinaryTravelRuntime(forged,BDirectAttackInput.Digest(forged),f.binding,node,g,10000,c,BDirectAttackInput.Digest(c)));var changed=(JObject)c.DeepClone();changed["baseSpeedMillimetersPerSecond"]=9999;Assert.Throws<ArgumentException>(()=>BDirectAttackBasicLoop.RestoreOrdinaryTravelRuntime(snapshot,BDirectAttackInput.Digest(snapshot),f.binding,node,g,10000,changed,BDirectAttackInput.Digest(changed)));Assert.Throws<ArgumentException>(()=>BDirectAttackBasicLoop.RestoreOrdinaryTravelRuntime(snapshot,"changed-pin",f.binding,node,g,10000,c,BDirectAttackInput.Digest(c)));}
  [Test] public void ConfigMustBeOriginalExplicitAndCannotRestoreAOfferEffects(){var f=BNamedOperatorSourceTests.Native();var node=BInterceptSourceTests.Read(BInterceptSourceTests.Sample()).OriginalSource;var g=BOrdinaryGeometryTests.Geometry(f.binding);var c=Rail();Assert.Throws<ArgumentException>(()=>BDirectAttackBasicLoop.CreateOrdinaryTravelRuntime(f.binding,node,g,10000,c,"wrong"));Assert.Throws<ArgumentException>(()=>Native(global::CombatRailJourneyTests.Config()));c.Remove("baseSpeedMillimetersPerSecond");Assert.Throws<ArgumentException>(()=>Native(c));c=Rail();c.Remove("throttleCruiseBps");Assert.Throws<ArgumentException>(()=>Native(c));}
  [Test] public void MotionFailureAndCapacityFailureLeaveOriginalEntireStateUnchanged(){var n=Native(null,32);for(int i=0;i<32;i++)n.SetTravelThrottle("accepted"+i,7000);var p=n.Capture();Assert.Throws<ArgumentException>(()=>n.Advance("capacity",10000000,500));Assert.IsTrue(JToken.DeepEquals(p,n.Capture()));var c=Rail();var many=Native(c);p=many.Capture();Assert.Throws<ArgumentException>(()=>many.Advance("elapsed-overflow",long.MaxValue,1));Assert.IsTrue(JToken.DeepEquals(p,many.Capture()));}
  [Test] public void ExistingObservationCapturesRealTravelWithoutClaimingServerProof(){var n=Native();using(var s=new BSafeMaintenanceObservationSource(n)){n.Advance("step",10000000,500);var p=s.ObserveAccepted("step",0);Assert.AreEqual(10000,(long)p["native"]["travel"]["motion"]["distanceMm"]);Assert.IsFalse(s.CanPrepareTrustedMaintenance);n.SetPaused("p",true);s.ObserveAccepted("p",1);Assert.IsTrue((bool)s.Capture()["native"]["travel"]["stopped"]);n.SetPaused("r",false);Assert.Throws<InvalidOperationException>(()=>s.RequireUnchanged(2,(string)s.Capture()["nativeHash"]));}}
  [Test] public void InstalledHazardsRemainPendingEvenWhenClockAndTravelArePaused(){var n=Native();n.Advance("step",10000000,500);n.SetPaused("pause",true);var h=n.ObserveResidualHazards();Assert.IsTrue(h.Known);Assert.IsFalse(h.Settled);Assert.Throws<InvalidOperationException>(()=>h.RequireSettled());Assert.That(((JArray)h.Capture()["owners"]).Count,Is.EqualTo(5));h.Capture()["owners"][0]["pending"]=false;Assert.IsFalse(h.Settled);File.WriteAllText(Qa+"pending-hazard-owners.json",h.Capture().ToString());}
  [Test] public void MissingExecutorAndActualUnboundProjectileRemainUnknown(){var node=BInterceptSourceTests.Read(BInterceptSourceTests.Sample()).OriginalSource;var b=BGunnerInterceptRuntimeTests.Kyle(node);var n=BDirectAttackBasicLoop.CreateBoardingEventsRuntime(b,node,BWaveBoardingRuntimeTests.Paths(b.Composition.Attack),10000);Assert.IsFalse(n.ObserveResidualHazards().Known);n.Advance("unbound-launch",100000000,10000);Assert.IsTrue((bool)n.Capture()["waveEntry"]["unknownProjectile"]);Assert.IsFalse(n.ObserveResidualHazards().Known);Assert.Throws<InvalidOperationException>(()=>n.ObserveResidualHazards().RequireSettled());File.WriteAllText(Qa+"unknown-hazard-owners.json",n.ObserveResidualHazards().Capture().ToString());}
  [Test] public void ActualTerminalStopsTravelAndSettlesInstalledOwnersButGrantsNoSafeEvent(){var receipt=BInterceptSourceTests.Read(BInterceptSourceTests.Sample());var b=BOrdinaryGeometryTests.Stress(BInterceptSourceTests.Sample());var g=BOrdinaryGeometryTests.Geometry(b,BOrdinaryGeometryTests.ShortCarAsset());var c=Rail();var n=BDirectAttackBasicLoop.CreateOrdinaryTravelRuntime(b,receipt.OriginalSource,g,10000,c,BDirectAttackInput.Digest(c),true);int hit=0;for(int i=0;i<60&&n.Outcome=="RUNNING";i++){n.Advance("end-step-"+i,10000000,500);foreach(var life in ((JArray)n.Capture()["boarding"]["lives"]).Where(x=>(bool)x["registered"]&&(bool)x["targetable"]).ToArray()){var state=n.Capture();string id=(string)life["id"];var frame=n.ObserveOrdinaryGeometry("op_kyle",id,n.Tick,(long)state["spatialSource"]["revision"],g.Hash);if(!(bool)frame["eligible"]||(long)state["state"]["direct"]["next"]["op_kyle"]>n.Tick)continue;n.ApplyWaveBasic("end-hit-"+hit++,"op_kyle",id,(long)life["generation"]);}}Assert.AreEqual("VICTORY",n.Outcome);Assert.AreEqual(2,(int)n.Capture()["travel"]["motion"]["completedWaves"]);var h=n.ObserveResidualHazards();Assert.IsTrue(h.Known);Assert.IsTrue(h.Settled);h.RequireSettled();var distance=Distance(n);n.Advance("terminal-noop",10000000,500);Assert.AreEqual(distance,Distance(n));Assert.IsTrue((bool)n.Capture()["travel"]["stopped"]);File.WriteAllText(Qa+"terminal-travel-hazards.json",new JObject{["native"]=n.Capture(),["hazards"]=h.Capture(),["serverTrusted"]=false}.ToString());}
 }
}
